<?php
require_admin();
header('Cache-Control: private, no-store');
require_once __DIR__.'/login_notice_store.php';
$notice=cds_ln_load();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals(cds_ln_csrf(),(is_string($_POST['csrf']??null)?$_POST['csrf']:''))){http_response_code(403);exit('Phiên làm việc không hợp lệ.');}
    try{
        cds_ln_save($_POST,current_user());flash('Đã lưu thông báo và lịch hiển thị.','success');
        header('Location: '.BASE_URL.'admin.php?view=login_notice');exit;
    }catch(RuntimeException $e){
        $error=$e->getMessage();
        foreach(['title','body','icon','theme'] as $key)$notice[$key]=is_string($_POST[$key]??null)?$_POST[$key]:'';
        $notice['enabled']=!empty($_POST['enabled']);
    }
}
